import{GEOMETRY_PINS as P}from'../geometry-pins.mjs';
const owned=new WeakMap(),hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function loadS4EncounterGeometry({readBytes,signal}={}){if(typeof readBytes!=='function')throw Error('ENCOUNTER_PINNED_READER_REQUIRED');const read=async p=>{if(signal?.aborted)throw Error('ENCOUNTER_LOAD_ABORTED');const raw=await readBytes(p),b=raw instanceof ArrayBuffer?new Uint8Array(raw.slice(0)):new Uint8Array(raw);if(b.length!==p.bytes||await hash(b)!==p.sha256)throw Error('ENCOUNTER_GEOMETRY_PIN_MISMATCH');if(signal?.aborted)throw Error('ENCOUNTER_LOAD_ABORTED');return b};await read(P.selection);const maps=new Map();for(const m of P.maps){const safe=await read(m.selectedSolidSafe),habitats=[];for(const h of m.habitats)habitats.push({id:h.tableId,mask:await read(h.mask)});maps.set(m.mapId,{mapId:m.mapId,imageSHA:m.imageSHA,maskSHA:m.originalSafeSHA,safe,habitats})}const g=Object.freeze({});owned.set(g,maps);return g}
export function encounterMap(g,id){const m=owned.get(g)?.get(id);if(!m)throw Error('REGISTERED_ENCOUNTER_GEOMETRY_REQUIRED');return Object.freeze({imageSHA:m.imageSHA,maskSHA:m.maskSHA,safeMask:()=>new Uint8Array(m.safe),tableAt:([x,y])=>Number.isInteger(x)&&Number.isInteger(y)&&x>=0&&x<1536&&y>=0&&y<1024&&m.safe[y*1536+x]===1?m.habitats.find(h=>h.mask[y*1536+x]===1)?.id??null:null})}
